import java.util.Scanner;

public class Main {
    static final long MOD = 1000000007;
    static final int maxn = 1000007;
    static long P, K;
    static long[] vis = new long[maxn];
    static long[] num = new long[maxn];

    static long getnum(int pos) {
        long tep = (num[pos] * pos) % MOD;
        tep = (tep + 1) % MOD;
        long re = 1;
        for (int i = 1; i <= num[pos]; i++) {
            re = (re * tep) % MOD;
        }
        return re;
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        P = sc.nextLong();
        K = sc.nextLong();

        for (int i = 0; i < maxn; i++) {
            vis[i] = 0;
            num[i] = 0;
        }

        if (K == 0) {
            long tepre = 1;
            for (int i = 1; i < P; i++) {
                tepre = (tepre * P) % MOD;
            }
            System.out.println(tepre);
            return;
        }

        if (K == 1) {
            long tepre = 1;
            for (int i = 1; i <= P; i++) {
                tepre = (tepre * P) % MOD;
            }
            System.out.println(tepre);
            return;
        }

        for (int i = 0; i < P; i++) {
            if (vis[i] == 0) {
                long tepnum = 0;
                long pos = i;
                while (vis[(int) pos] == 0) {
                    vis[(int) pos] = 1;
                    tepnum++;
                    pos = (K * pos) % P;
                }
                num[(int) tepnum]++;
            }
        }

        long re = 1;
        for (int i = 2; i < P; i++) {
            if (num[i] != 0) {
                re = (re * getnum(i)) % MOD;
            }
        }

        System.out.println(re);
        sc.close();
    }
}
